def get_neighbors(pos: Position, grid_size: int, obstacles: Set[Position]) -> List[Position]:
    neighbors = []
    for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
        nx, ny = pos.x + dx, pos.y + dy
        if 0 <= nx < grid_size and 0 <= ny < grid_size:
            if Position(nx, ny) not in obstacles:
                neighbors.append(Position(nx, ny))
    return neighbors

def a_star(start: Position, goal: Position, grid_size: int, obstacles: Set[Position]) -> List[Position]:
    open_set = [(0, start)]
    came_from = {}
    g_score = {start: 0}
    f_score = {start: start.distance_to(goal)}

    while open_set:
        _, current = heapq.heappop(open_set)
        if current == goal:
            # Reconstruct path
            path = [current]
            while current in came_from:
                current = came_from[current]
                path.append(current)
            return path[::-1]

        for neighbor in get_neighbors(current, grid_size, obstacles):
            tentative_g = g_score[current] + 1
            if neighbor not in g_score or tentative_g < g_score[neighbor]:
                came_from[neighbor] = current
                g_score[neighbor] = tentative_g
                f_score[neighbor] = tentative_g + neighbor.distance_to(goal)
                heapq.heappush(open_set, (f_score[neighbor], neighbor))

    return []  # No path found

