    def deliver(self, agents: List[Agent], current_turn: int):
        # Deliver messages to all agents in same team
        for msg in self.message_queue[:]:
            if msg.turn < current_turn:  # Only deliver messages from previous turns
                for agent in agents:
                    if agent.team == self._get_sender_team(msg.sender_id):
                        self.received_messages[agent.id].append(msg)
                self.message_queue.remove(msg)

    def _get_sender_team(self, sender_id: str) -> str:
