import random
import math
from enum import Enum
from typing import List, Dict, Tuple, Optional, Set
from dataclasses import dataclass, field
from collections import defaultdict
import heapq

# =====================
# Core Data Structures
# =====================

class AgentRole(Enum):
    ATTACKER = "attacker"
    DEFENDER = "defender"
    SCOUT = "scout"

class AbilityType(Enum):
    SPEED_BOOST = "speed_boost"
    HEAL = "heal"
    SHIELD = "shield"

class ObjectiveType(Enum):
    CAPTURE_FLAG = "capture_flag"
    DEFEND_BASE = "defend_base"
    ELIMINATE_ENEMIES = "eliminate_enemies"

class GameState(Enum):
    SETUP = "setup"
    PLAYING = "playing"
    ENDED = "ended"

@dataclass
class Position:
    x: float
    y: float

    def distance_to(self, other: 'Position') -> float:
        return math.hypot(self.x - other.x, self.y - other.y)

@dataclass
class Agent:
    id: str
    team: str  # 'red' or 'blue'
    role: AgentRole
    position: Position
    health: float = 100.0
    max_health: float = 100.0
    shield: float = 0.0
    speed: float = 1.0
    abilities: Dict[AbilityType, float] = field(default_factory=dict)  # cooldown timers
    objective_progress: float = 0.0  # e.g., flag capture progress
    is_alive: bool = True

    def take_damage(self, damage: float):
        if not self.is_alive:
            return
        # Shield absorbs damage first
        shield_absorb = min(self.shield, damage)
        self.shield -= shield_absorb
        damage -= shield_absorb

        self.health -= damage
        if self.health <= 0:
            self.health = 0
            self.is_alive = False
            self.shield = 0.0

    def heal(self, amount: float):
        if not self.is_alive:
            return
        self.health = min(self.health + amount, self.max_health)

    def activate_shield(self, duration: float = 5.0):
        if not self.is_alive:
            return
        self.shield = 30.0
        self.abilities[AbilityType.SHIELD] = duration

    def activate_speed_boost(self, duration: float = 3.0):
        if not self.is_alive:
            return
        self.abilities[AbilityType.SPEED_BOOST] = duration

    def activate_heal(self, amount: float = 25.0):
        if not self.is_alive:
            return
        self.abilities[AbilityType.HEAL] = 10.0  # cooldown
        self.heal(amount)

@dataclass
class Objective:
    id: str
    type: ObjectiveType
    position: Position
    team_control: Optional[str] = None  # 'red', 'blue', or None
    progress: float = 0.0  # 0.0 to 100.0
    radius: float = 10.0

    def is_captured_by(self, team: str) -> bool:
