# Communication System
# =====================

class CommunicationSystem:
    def __init__(self, agents: List[Agent]):
        self.agents = {a.id: a for a in agents}
        self.message_queue: List[Message] = []
        self.received_messages: Dict[str, List[Message]] = defaultdict(list)
        self.broadcast_range = 100.0

    def broadcast(self, message: Message):
        """Broadcast message to teammates within range"""
        sender = self.agents.get(message.sender_id)
        if not sender or not sender.is_alive:
            return

        for agent in self.agents.values():
            if agent.team == sender.team and agent.id != sender.id and agent.is_alive:
                if sender.position.distance_to(agent.position) <= self.broadcast_range:
                    self.received_messages[agent.id].append(message)

    def send_direct(self, sender_id: str, receiver_id: str, message: Message):
        """Send message to a specific teammate"""
        if receiver_id in self.agents:
            self.received_messages[receiver_id].append(message)

    def get_unread_messages(self, agent_id: str) -> List[Message]:
        return self.received_messages.get(agent_id, [])

    def clear_messages(self, agent_id: str):
        self.received_messages[agent_id] = []

# =====================
# AI Agent Controller
# =====================

class AIController:
    def __init__(self, agent: Agent, objectives: List[Objective], team_objectives: List[Objective]):
        self.agent = agent
        self.objectives = objectives
        self.team_objectives = team_objectives
        self.current_plan: Optional[str] = None
        self.target_position: Optional[Position] = None
        self.target_agent_id: Optional[str] = None
        self.last_known_enemy_positions: Dict[str, Position] = {}
        self.last_known_objective_status: Dict[str, float] = {}

    def update(self, all_agents: List[Agent], messages: List[Message], dt: float):
        # Process incoming messages
        self._process_messages(messages)

        # Update cooldowns
        self._update_abilities(dt)

        # Decide next action
        self._make_decision()

        # Execute movement and actions
        self._execute_action(all_agents, dt)

    def _process_messages(self, messages: List[Message]):
        for msg in messages:
            if msg.message_type == 'enemy_sighted':
                enemy_id = msg.content.get('enemy_id')
                if enemy_id:
                    self.last_known_enemy_positions[enemy_id] = Position(
                        msg.content['x'], msg.content['y']
                    )
            elif msg.message_type == 'objective_status':
                obj_id = msg.content.get('objective_id')
                if obj_id:
                    self.last_known_objective_status[obj_id] = msg.content.get('progress', 0.0)

    def _update_abilities(self, dt: float):
        # Reduce cooldowns
        for ability in list(self.agent.abilities.keys()):
            self.agent.abilities[ability] -= dt
            if self.agent.abilities[ability] <= 0:
                del self.agent.abilities[ability]

        # Apply active effects
        if AbilityType.SPEED_BOOST in self.agent.abilities:
            self.agent.speed = 2.0
        else:
            self.agent.speed = 1.0

    def _make_decision(self):
        # Priority: 1) Capture/defend objective, 2) Eliminate enemies, 3) Support teammates

        # Find nearest objective
        nearest_obj = self._find_nearest_objective()

        if nearest_obj:
            # Determine if objective is contested or ours
            if nearest_obj.team_control == self.agent.team:
                # Defend our objective
                if self.agent.role == AgentRole.DEFENDER:
                    self.target_position = nearest_obj.position
                    self.current_plan = f"defend_{nearest_obj.id}"
                else:
                    # Attackers help defend too
                    self.target_position = nearest_obj.position
                    self.current_plan = f"support_defense_{nearest_obj.id}"
            else:
                # Capture enemy objective
                if self.agent.role == AgentRole.ATTACKER:
                    self.target_position = nearest_obj.position
                    self.current_plan = f"capture_{nearest_obj.id}"
                else:
                    # Scouts and defenders assist
                    self.target_position = nearest_obj.position
                    self.current_plan = f"assist_capture_{nearest_obj.id}"
        else:
            # Look for enemies
            nearest_enemy = self._find_nearest_enemy()
            if nearest_enemy:
                self.target_agent_id = nearest_enemy.id
                self.target_position = nearest_enemy.position
                self.current_plan = "engage_enemy"
            else:
                # Default: patrol or scout
                self._set_patrol_behavior()

