        if ability == ABILITY_SPEED_BOOST:
            self.speed = 2.0
            self.abilities[ABILITY_SPEED_BOOST] = 30  # 1 second at 30 FPS
        elif ability == ABILITY_HEAL:
            self.health = min(self.health + 50, self.max_health)
            self.abilities[ABILITY_HEAL] = 60
        elif ability == ABILITY_SHIELD:
            self.shield = 30
            self.abilities[ABILITY_SHIELD] = 45
        return True

    def update_abilities(self):
        for ability in self.abilities:
            if self.abilities[ability] > 0:
                self.abilities[ability] -= 1
        if self.speed > 1.0:
            self.speed = 1.0

    def take_damage(self, damage: int):
        if self.shield > 0:
            shield_reduction = min(self.shield, damage)
            self.shield -= shield_reduction
            damage -= shield_reduction
        if damage > 0:
            self.health -= damage
            if self.health <= 0:
                self.health = 0
                self.is_dead = True

    def heal(self, amount: int):
        self.health = min(self.health + amount, self.max_health)

    def reset(self):
        self.health = self.max_health
        self.shield = 0
        self.speed = 1.0
        self.is_dead = False
        self.has_flag = False
        self.last_known_enemies.clear()
        self.last_saw_flag = None
        self.objective_status.clear()

