        self.broadcast_range = 15  # max distance for message reception

    def send_message(self, sender: Agent, message: GameMessage):
        message.timestamp = 0  # Will be set by game loop
        self.message_queue.append(message)

    def broadcast_to_team(self, sender: Agent, message_type: str, data: Dict):
        message = GameMessage(
            sender_id=sender.id,
            message_type=message_type,
            data=data
        )
        self.send_message(sender, message)

    def update(self, agents: List[Agent]):
        # Process messages and deliver to agents within range
        delivered = []
        for msg in self.message_queue:
            sender = next((a for a in agents if a.id == msg.sender_id), None)
            if not sender:
                continue

            for agent in agents:
                if agent.id == msg.sender_id or agent.team != sender.team:
                    continue
                if sender.position.distance_to(agent.position) <= self.broadcast_range:
                    self.received_messages[agent.id].append(msg)
                    delivered.append(msg)

        # Remove delivered messages
        self.message_queue = [m for m in self.message_queue if m not in delivered]

